const IssueCard = (props) => {
  const {
    id,
    topic,
    ctaLabel,
    status,
    progressPercent,
    showProgressBar,
    scheduledDate,
    iconUrl,
    tags,
    lastEditedAt,
  } = props;

  const safePercent = typeof progressPercent === 'number' ? Math.max(0, Math.min(100, progressPercent)) : 0;
  const hasProgress = showProgressBar === true && typeof progressPercent === 'number';
  const statusColor =
    status === 'Sent'
      ? 'bg-green-100 text-green-700'
      : status === 'Ready'
      ? 'bg-blue-100 text-blue-700'
      : status === 'Draft'
      ? 'bg-gray-100 text-gray-700'
      : 'bg-gray-100 text-gray-700';

  const scheduled =
    scheduledDate ? new Date(scheduledDate).toLocaleString() : 'Not scheduled';
  const edited =
    lastEditedAt ? new Date(lastEditedAt).toLocaleString() : 'Unknown';

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow">
      <div className="flex items-start justify-between">
        <div className="flex items-center">
          {iconUrl ? (
            <img
              src={iconUrl}
              alt={topic || 'Issue icon'}
              className="w-10 h-10 rounded-md object-cover mr-3"
            />
          ) : (
            <div className="w-10 h-10 mr-3 rounded-md bg-gray-100 flex items-center justify-center text-lg">
              🗂️
            </div>
          )}
          <div>
            <h3 className="text-lg font-semibold text-gray-900 line-clamp-2">
              {topic || 'Untitled Issue'}
            </h3>
            <div className="mt-1 text-sm text-gray-500">
              <span className="mr-2">ID: {id || '—'}</span>
            </div>
          </div>
        </div>
        {status ? (
          <span className={`px-2 py-1 text-xs font-medium rounded ${statusColor}`}>
            {status}
          </span>
        ) : (
          <span className="px-2 py-1 text-xs font-medium rounded bg-gray-100 text-gray-700">
            Unknown
          </span>
        )}
      </div>

      <div className="mt-3 grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="p-3 bg-gray-50 rounded-md">
          <div className="text-xs text-gray-500">Scheduled</div>
          <div className="text-sm text-gray-900 mt-0.5">{scheduled}</div>
        </div>
        <div className="p-3 bg-gray-50 rounded-md">
          <div className="text-xs text-gray-500">Last edited</div>
          <div className="text-sm text-gray-900 mt-0.5">{edited}</div>
        </div>
        <div className="p-3 bg-gray-50 rounded-md">
          <div className="text-xs text-gray-500">Primary action</div>
          <div className="text-sm text-gray-900 mt-0.5">
            {ctaLabel || 'No action specified'}
          </div>
        </div>
      </div>

      {hasProgress ? (
        <div className="mt-4">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm font-medium text-gray-700">Progress</span>
            <span className="text-sm text-gray-600">{safePercent.toFixed(0)}%</span>
          </div>
          <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
            <div
              className="h-2 bg-blue-500 rounded-full transition-all"
              style={{ width: `${safePercent}%` }}
            />
          </div>
        </div>
      ) : null}

      {Array.isArray(tags) && tags.length > 0 ? (
        <div className="mt-4 flex flex-wrap gap-2">
          {tags.map((t, i) => (
            <span
              key={i}
              className="px-2 py-1 text-xs bg-gray-100 text-gray-700 rounded"
            >
              {t || '—'}
            </span>
          ))}
        </div>
      ) : (
        <div className="mt-4 text-sm text-gray-500">No tags</div>
      )}
    </div>
  );
};

