const PlanningCalendarBoard = (props) => {
  const {
    startDate,
    weeks = 4,
    scheduledIssues = [],
    backlogIdeas = [],
    statusesShown = [],
    legendItems = [],
    title = 'Planning Calendar',
    subtitle = '',
    generatedAt,
    showWeekNumbers = true,
    showBacklog = true,
    calendarDensity = 'comfortable',
    children,
  } = props;

  const safeStart = startDate ? new Date(startDate) : new Date();
  const safeGeneratedAt = generatedAt ? new Date(generatedAt) : new Date();

  const dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  const cellHeight = calendarDensity === 'compact' ? 'h-16' : 'h-24';

  const addDays = (date, days) => {
    const d = new Date(date);
    d.setDate(d.getDate() + days);
    return d;
  };

  const getWeekNumber = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    const dayNum = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dayNum);
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(),0,1));
    const weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
    return weekNo;
  };

  const formatShort = (date) => {
    try {
      return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    } catch (e) {
      return '';
    }
  };

  const formatFull = (date) => {
    try {
      return date.toLocaleDateString();
    } catch (e) {
      return String(date);
    }
  };

  const weeksArray = Array.from({ length: typeof weeks === 'number' && weeks > 0 ? weeks : 4 }, (_, w) => w);
  const daysArray = Array.from({ length: 7 }, (_, d) => d);

  const getDisplayLabel = (obj) => {
    if (!obj || typeof obj !== 'object') return '';
    return obj.name || obj.label || obj.title || obj.key || '';
  };

  const getDisplayColor = (obj) => {
    if (!obj || typeof obj !== 'object') return 'bg-gray-200';
    const c = obj.color || obj.bg || '';
    if (typeof c === 'string' && c.trim() !== '') return c;
    return 'bg-gray-200';
  };

  const totalScheduled = Array.isArray(scheduledIssues) ? scheduledIssues.length : 0;
  const totalBacklog = Array.isArray(backlogIdeas) ? backlogIdeas.length : 0;

  const headerStart = new Date(safeStart);
  const headerDates = daysArray.map((d) => addDays(headerStart, d));

  return (
    <div className="w-full max-w-3xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4">
      <div className="flex items-start justify-between">
        <div>
          <h3 className="text-lg font-semibold text-gray-900">{title}</h3>
          {subtitle ? <div className="text-sm text-gray-600 mt-1">{subtitle}</div> : null}
        </div>
        <div className="text-xs text-gray-500">
          Generated {formatFull(safeGeneratedAt)}
        </div>
      </div>

      <div className="mt-4 grid gap-4 md:grid-cols-3">
        <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
          <div className="text-xs text-gray-500">Start Date</div>
          <div className="text-sm font-medium text-gray-900 mt-1">{formatFull(safeStart)}</div>
        </div>
        <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
          <div className="text-xs text-gray-500">Visible Range</div>
          <div className="text-sm font-medium text-gray-900 mt-1">
            {typeof weeks === 'number' ? weeks.toLocaleString() : '—'} week{typeof weeks === 'number' && weeks !== 1 ? 's' : ''}
          </div>
        </div>
        <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
          <div className="text-xs text-gray-500">Items</div>
          <div className="text-sm text-gray-900 mt-1">
            <span className="font-medium">{totalScheduled.toLocaleString()}</span> scheduled
            {showBacklog ? <span className="text-gray-500"> • </span> : null}
            {showBacklog ? <span><span className="font-medium">{totalBacklog.toLocaleString()}</span> backlog</span> : null}
          </div>
        </div>
      </div>

      {Array.isArray(statusesShown) && statusesShown.length > 0 ? (
        <div className="mt-4">
          <div className="text-xs font-medium text-gray-700 mb-2">Statuses Shown</div>
          <div className="flex flex-wrap gap-2">
            {statusesShown.map((s, i) => (
              <span key={i} className="px-2 py-1 text-xs bg-blue-50 text-blue-700 rounded border border-blue-100">
                {getDisplayLabel(s) || 'Status'}
              </span>
            ))}
          </div>
        </div>
      ) : null}

      {Array.isArray(legendItems) && legendItems.length > 0 ? (
        <div className="mt-3">
          <div className="text-xs font-medium text-gray-700 mb-2">Legend</div>
          <div className="flex flex-wrap gap-3">
            {legendItems.map((l, i) => (
              <div key={i} className="flex items-center text-sm text-gray-700">
                <span className={"inline-block w-3 h-3 rounded mr-2 border border-gray-200 " + getDisplayColor(l)}></span>
                <span className="text-gray-600">{getDisplayLabel(l) || 'Item'}</span>
              </div>
            ))}
          </div>
        </div>
      ) : null}

      <div className="mt-6">
        <div className="mb-2 flex items-center justify-between">
          <div className="text-sm font-semibold text-gray-800">Calendar</div>
          <div className="text-xs text-gray-500">
            Density: {calendarDensity === 'compact' ? 'Compact' : 'Comfortable'}
          </div>
        </div>

        <div className="overflow-x-auto">
          <div className="min-w-[640px]">
            <div className={(showWeekNumbers ? 'grid-cols-8' : 'grid-cols-7') + " grid text-xs bg-gray-50 border border-gray-200 rounded-t-md"}>
              {showWeekNumbers ? (
                <div className="p-2 text-gray-500 font-medium border-r border-gray-200">Wk</div>
              ) : null}
              {headerDates.map((d, idx) => (
                <div key={idx} className={(idx < 6 ? 'border-r ' : '') + "p-2 text-gray-600 font-medium border-gray-200"}>
                  <div>{dayNames[d.getDay()]}</div>
                </div>
              ))}
            </div>

            <div className={(showWeekNumbers ? 'grid-cols-8' : 'grid-cols-7') + " grid border-x border-b border-gray-200 rounded-b-md"}>
              {weeksArray.map((w) => {
                const rowStart = addDays(safeStart, w * 7);
                const weekNo = getWeekNumber(rowStart);
                return (
                  <div key={w} className={(showWeekNumbers ? 'contents' : '')}>
                    {showWeekNumbers ? (
                      <div className={"p-2 border-r border-gray-200 bg-gray-50 text-xs text-gray-600"}>
                        <span className="px-2 py-1 rounded bg-gray-100 text-gray-700">{weekNo}</span>
                      </div>
                    ) : null}
                    {daysArray.map((dIdx) => {
                      const cellDate = addDays(rowStart, dIdx);
                      return (
                        <div key={dIdx} className={(dIdx < 6 ? 'border-r ' : '') + "border-gray-200 " + cellHeight + " p-2"}>
                          <div className="flex items-center justify-between">
                            <span className="text-xs text-gray-500">{formatShort(cellDate)}</span>
                          </div>
                          <div className="mt-1 h-px bg-gray-100"></div>
                        </div>
                      );
                    })}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div className="mt-4 p-3 bg-blue-50 border border-blue-100 rounded-md">
          <div className="text-sm font-medium text-blue-900">Scheduled Items</div>
          <div className="text-xs text-blue-700 mt-1">
            Display-only preview of items placed within the planning period.
          </div>
          <div className="mt-3 space-y-2">
            {children ? (
              <div className="space-y-2">
                {children}
              </div>
            ) : (
              <div className="p-3 bg-white rounded border border-blue-100 text-sm text-blue-900">
                No scheduled items provided. Pass IssueCard components as children to display them here.
              </div>
            )}
          </div>
        </div>
      </div>

      {showBacklog ? (
        <div className="mt-6">
          <div className="mb-2 flex items-center justify-between">
            <div className="text-sm font-semibold text-gray-800">Backlog</div>
            <div className="text-xs text-gray-500">{totalBacklog.toLocaleString()} item{totalBacklog === 1 ? '' : 's'}</div>
          </div>
          <div className="p-3 bg-gray-50 border border-gray-200 rounded-md text-sm text-gray-600">
            Backlog items are not rendered here. This section summarizes the backlog count.
          </div>
        </div>
      ) : null}
    </div>
  );
};

