const TimeBlockScheduleGrid = (props) => {
  const {
    date,
    timezone,
    generatedAt,
    blocks = [],
    goalTargetMinutes,
    goalCompletedMinutes,
    progressLabel,
    showNowIndicator = true,
    showConflictBadges = true,
    showProgressBar = true,
    gridStartHour = 6,
    gridEndHour = 22,
  } = props;

  const safeStartHour = typeof gridStartHour === 'number' ? gridStartHour : 6;
  const safeEndHour = typeof gridEndHour === 'number' ? gridEndHour : 22;
  const startHour = Math.max(0, Math.min(23, safeStartHour));
  const endHour = Math.max(startHour + 1, Math.min(24, safeEndHour));

  const minutesPerHour = 60;
  const totalMinutes = (endHour - startHour) * minutesPerHour;
  const pxPerMinute = 0.6; // 36px per hour for compact display
  const gridHeight = totalMinutes * pxPerMinute;

  const fmtDate = (d, tz) => {
    if (!d) return '';
    try {
      return new Date(d).toLocaleDateString(undefined, {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        timeZone: tz || undefined,
      });
    } catch (e) {
      return new Date(d).toLocaleDateString();
    }
  };

  const fmtTime = (d, tz) => {
    try {
      return new Date(d).toLocaleTimeString(undefined, {
        hour: '2-digit',
        minute: '2-digit',
        timeZone: tz || undefined,
      });
    } catch (e) {
      return new Date(d).toLocaleTimeString();
    }
  };

  const parseHHMM = (str) => {
    if (typeof str !== 'string') return null;
    const parts = str.split(':');
    if (parts.length < 2) return null;
    const h = Number(parts[0]);
    const m = Number(parts[1]);
    if (isNaN(h) || isNaN(m)) return null;
    return h * 60 + m;
    };

  const getMinutesFromMidnightInTz = (d, tz) => {
    try {
      const dt = new Date(d);
      const parts = new Intl.DateTimeFormat('en-US', {
        hour12: false,
        timeZone: tz || undefined,
        hour: '2-digit',
        minute: '2-digit',
      }).formatToParts(dt);
      const hour = Number(parts.find(p => p.type === 'hour')?.value || '0');
      const minute = Number(parts.find(p => p.type === 'minute')?.value || '0');
      return hour * 60 + minute;
    } catch (e) {
      const local = new Date(d);
      return local.getHours() * 60 + local.getMinutes();
    }
  };

  const toMinutes = (val) => {
    if (val == null) return null;
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
      const hhmm = parseHHMM(val);
      if (hhmm != null) return hhmm;
      const iso = Date.parse(val);
      if (!isNaN(iso)) return getMinutesFromMidnightInTz(val, timezone);
    }
    if (val instanceof Date) return getMinutesFromMidnightInTz(val, timezone);
    return null;
  };

  const clamp = (n, min, max) => {
    const num = Number(n);
    if (isNaN(num)) return min;
    return Math.max(min, Math.min(max, num));
  };

  const startMinute = startHour * 60;
  const endMinute = endHour * 60;

  const normalizedBlocks = Array.isArray(blocks) ? blocks.map((b, idx) => {
    const start = toMinutes(b.start ?? b.startTime);
    const end = toMinutes(b.end ?? b.endTime);
    const safeStart = start == null ? startMinute : clamp(start, startMinute, endMinute);
    const safeEnd = end == null ? safeStart + 30 : clamp(end, startMinute, endMinute);
    const duration = Math.max(5, safeEnd - safeStart);
    return {
      key: b.id || b.key || idx,
      title: b.title || b.name || 'Untitled',
      subtitle: b.subtitle || b.description || '',
      start: safeStart,
      end: safeEnd,
      duration,
      color: b.color || 'blue',
      isConflict: !!(b.isConflict || b.conflict),
      meta: b.meta || null,
      raw: b,
    };
  }) : [];

  const hourMarks = [];
  for (let h = startHour; h <= endHour; h++) {
    const m = (h - startHour) * minutesPerHour;
    hourMarks.push({
      hour: h,
      minuteFromStart: m,
      label: new Date(2000, 0, 1, h, 0, 0).toLocaleTimeString(undefined, { hour: 'numeric' }),
    });
  }

  const nowMinutes = (() => {
    if (!showNowIndicator) return null;
    const baseDate = date ? new Date(date) : new Date();
    const now = generatedAt ? new Date(generatedAt) : new Date();
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone || undefined,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).formatToParts(baseDate);
    const y = Number(parts.find(p => p.type === 'year')?.value || now.getFullYear());
    const mo = Number(parts.find(p => p.type === 'month')?.value || (now.getMonth() + 1));
    const da = Number(parts.find(p => p.type === 'day')?.value || now.getDate());
    const nowParts = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone || undefined,
      hour12: false,
      hour: '2-digit',
      minute: '2-digit',
    }).formatToParts(new Date());
    const hh = Number(nowParts.find(p => p.type === 'hour')?.value || now.getHours());
    const mm = Number(nowParts.find(p => p.type === 'minute')?.value || now.getMinutes());
    const current = new Date(y, mo - 1, da, hh, mm, 0);
    return getMinutesFromMidnightInTz(current, timezone);
  })();

  const nowOffset = nowMinutes == null ? null : clamp(nowMinutes, startMinute, endMinute) - startMinute;

  const progressPct = (() => {
    const target = isNaN(Number(goalTargetMinutes)) ? 0 : Number(goalTargetMinutes);
    const done = isNaN(Number(goalCompletedMinutes)) ? 0 : Number(goalCompletedMinutes);
    if (target <= 0) return 0;
    return Math.max(0, Math.min(100, Math.round((done / target) * 100)));
  })();

  const colorClass = (c) => {
    if (c === 'green') return 'bg-green-100 border-green-300 text-green-800';
    if (c === 'blue') return 'bg-blue-100 border-blue-300 text-blue-800';
    if (c === 'yellow') return 'bg-yellow-100 border-yellow-300 text-yellow-800';
    if (c === 'red') return 'bg-red-100 border-red-300 text-red-800';
    if (c === 'purple') return 'bg-purple-100 border-purple-300 text-purple-800';
    if (c === 'gray' || c === 'grey') return 'bg-gray-100 border-gray-300 text-gray-800';
    return 'bg-blue-100 border-blue-300 text-blue-800';
  };

  const borderAccent = (c) => {
    if (c === 'green') return 'border-l-green-500';
    if (c === 'blue') return 'border-l-blue-500';
    if (c === 'yellow') return 'border-l-yellow-500';
    if (c === 'red') return 'border-l-red-500';
    if (c === 'purple') return 'border-l-purple-500';
    if (c === 'gray' || c === 'grey') return 'border-l-gray-500';
    return 'border-l-blue-500';
  };

  const emptyState = !Array.isArray(blocks) || blocks.length === 0;

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4">
      <div className="flex items-start justify-between mb-3">
        <div>
          <div className="text-lg font-semibold text-gray-900">Schedule</div>
          <div className="text-sm text-gray-600">
            {fmtDate(date || new Date(), timezone)}{timezone ? ` • ${timezone}` : ''}
          </div>
        </div>
        {generatedAt && (
          <div className="text-xs text-gray-500">
            Generated {fmtTime(generatedAt, timezone)}
          </div>
        )}
      </div>

      {showProgressBar ? (
        <div className="mb-4">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm text-gray-700">{progressLabel || 'Daily Progress'}</span>
            <span className="text-sm font-medium text-gray-900">{progressPct}%</span>
          </div>
          <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
            <div
              className="h-2 bg-blue-500"
              style={{ width: `${progressPct}%` }}
            />
          </div>
          <div className="mt-1 text-xs text-gray-500">
            {isNaN(Number(goalCompletedMinutes)) ? 0 : Number(goalCompletedMinutes)} min of {isNaN(Number(goalTargetMinutes)) ? 0 : Number(goalTargetMinutes)} min
          </div>
        </div>
      ) : null}

      <div className="relative w-full overflow-hidden rounded-md border border-gray-200">
        <div className="grid grid-cols-12">
          <div className="col-span-2 bg-gray-50 border-r border-gray-200">
            <div className="relative" style={{ height: gridHeight + 'px' }}>
              {hourMarks.map((m, idx) => (
                <div
                  key={idx}
                  className="text-xs text-gray-600 px-2"
                  style={{
                    position: 'absolute',
                    top: m.minuteFromStart * pxPerMinute - 8,
                    left: 0,
                  }}
                >
                  {m.label}
                </div>
              ))}
            </div>
          </div>

          <div className="col-span-10">
            <div className="relative" style={{ height: gridHeight + 'px' }}>
              {hourMarks.map((m, idx) => (
                <div
                  key={'line-' + idx}
                  className={idx === 0 ? 'border-t border-gray-200' : 'border-t border-dashed border-gray-200'}
                  style={{
                    position: 'absolute',
                    top: m.minuteFromStart * pxPerMinute,
                    left: 0,
                    right: 0,
                  }}
                />
              ))}

              {nowOffset != null && nowMinutes >= startMinute && nowMinutes <= endMinute ? (
                <div
                  className="pointer-events-none"
                  style={{
                    position: 'absolute',
                    top: nowOffset * pxPerMinute,
                    left: 0,
                    right: 0,
                  }}
                >
                  <div className="h-0.5 bg-blue-500 w-full" />
                </div>
              ) : null}

              {emptyState ? (
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="text-sm text-gray-500">
                    No time blocks to display
                  </div>
                </div>
              ) : null}

              {!emptyState ? normalizedBlocks.map((b) => {
                const top = (b.start - startMinute) * pxPerMinute;
                const height = Math.max(18, b.duration * pxPerMinute);
                const endTimeStr = (() => {
                  const h1 = Math.floor(b.start / 60);
                  const m1 = b.start % 60;
                  const h2 = Math.floor(b.end / 60);
                  const m2 = b.end % 60;
                  const s1 = new Date(2000, 0, 1, h1, m1).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
                  const s2 = new Date(2000, 0, 1, h2, m2).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
                  return `${s1} – ${s2}`;
                })();
                return (
                  <div
                    key={b.key}
                    className={`absolute right-2 left-2 border-l-4 rounded-md shadow-sm ${colorClass(b.color)} ${borderAccent(b.color)}`}
                    style={{
                      top: top,
                      height: height,
                    }}
                  >
                    <div className="p-2">
                      <div className="flex items-center justify-between">
                        <div className="text-sm font-medium text-gray-900 line-clamp-1">
                          {b.title}
                        </div>
                        {showConflictBadges && b.isConflict ? (
                          <span className="ml-2 px-1.5 py-0.5 text-[10px] font-semibold rounded bg-red-100 text-red-700 border border-red-200">
                            Conflict
                          </span>
                        ) : null}
                      </div>
                      <div className="text-xs text-gray-600">{endTimeStr}</div>
                      {b.subtitle ? (
