            <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
              <div className="text-xs text-gray-600">Total Blocks</div>
              <div className="text-lg font-semibold text-gray-900">{blocks.length.toLocaleString()}</div>
            </div>
            <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
              <div className="text-xs text-gray-600">Time Range</div>
              <div className="text-sm text-gray-900">
                {new Date(2000, 0, 1, startHour, 0).toLocaleTimeString(undefined, { hour: 'numeric' })} – {new Date(2000, 0, 1, endHour, 0).toLocaleTimeString(undefined, { hour: 'numeric' })}
              </div>
            </div>
            <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
              <div className="text-xs text-gray-600">Conflicts</div>
              <div className="text-lg font-semibold text-gray-900">
                {normalizedBlocks.filter(b => b.isConflict).length.toLocaleString()}
              </div>
